"use strict";
// Pure helpers are also exported to Node for non-browser tests.
const DSView={
  esc:s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),
  key:p=>`${p.d},${p.s}`,
  expand:r=>{const a=Array(4096).fill(null);if(!r)return a;for(let k=0;k<r.length;k++){const end=k+1<r.length?r[k+1][0]:4096;for(let i=r[k][0];i<end;i++)a[i]=r[k][1];}return a;},
  ideal:i=>{const a=Array(4096).fill(null);if(i.anchor==null||!i.period||!i.source)return a;for(let t=0;t<4096;t++){const delta=t-i.anchor,j=i.target+Math.floor(delta/i.period),at=((delta%i.period)+i.period)%i.period;if(j<0||j>=i.source.length)continue;a[t]=at<100?0:at<900?(i.source[j]>>Math.floor((at-100)/100))&1:1;}return a;},
  reconstruct:frames=>{const a=Array(4096).fill(null);for(const f of frames||[]){const bits=[0,...Array.from({length:8},(_,b)=>(f[3]>>b)&1),f[4]?0:1];bits.forEach((v,k)=>{for(let x=Math.max(0,f[1]+k*100);x<Math.min(4096,f[1]+(k+1)*100);x++)a[x]=v;});}return a;},
  options:(item,key)=>{const p=(item.profiles||[]).find(p=>DSView.key(p)===key);return p?p.scenarios:[];},
  csv:(rows,meta={})=>{const names=['session','source_sha256','alignment_policy','job_state','d','s','evaluated_windows','unresolved_windows','compared_local_bits','bit_errors_lower_bound','bit_errors_upper_bound','framing_errors_upper_bound','eligible_for_global_software_ranking','local_reference_windows','local_reference_bit_errors_upper_bound','local_reference_framing_errors_upper_bound'];const quote=v=>{let s=v==null?'':String(v);if(typeof v==='string'&&/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return names.map(quote).join(',')+'\n'+rows.map(r=>names.map(n=>quote(Object.prototype.hasOwnProperty.call(r,n)?r[n]:meta[n])).join(',')).join('\n');},
  svg:(values,lo,hi,color,markers=[])=>{const W=1100,H=150,L=42,R=18,top=24,bottom=105;lo=Math.max(0,lo);hi=Math.min(4095,hi);if(hi<=lo)hi=lo+1;const x=t=>L+(t-lo)*(W-L-R)/(hi-lo),y=v=>v?top:bottom;let d='',previous=null;for(let t=lo;t<=hi;t++){const v=values[t];if(v==null){previous=null;continue;}if(previous==null)d+=`M${x(t).toFixed(2)},${y(v)}`;else if(v!==previous)d+=`H${x(t).toFixed(2)}V${y(v)}`;previous=v;if(t===hi||values[t+1]==null)d+=`H${x(t).toFixed(2)}`;}let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}"><rect width="1100" height="150" fill="#fbfcfc"/><path d="M${L},${top}H${W-R}M${L},${bottom}H${W-R}" stroke="#dfe6e9" fill="none"/><text x="17" y="29" font-size="12">1</text><text x="17" y="110" font-size="12">0</text><path d="${d}" fill="none" stroke="${color}" stroke-width="2"/>`;if(lo<=2048&&hi>=2048)s+=`<path d="M${x(2048)},10V120" stroke="#b27d28" stroke-dasharray="4 4"/>`;for(const m of markers)if(m[0]>=lo&&m[0]<=hi)s+=`<circle cx="${x(m[0])}" cy="${y(m[1])}" r="4" fill="#9f3b86"/>`;s+=`<text x="${L}" y="140" font-size="12">${(lo*.01).toFixed(2)} μs</text><text x="${W-85}" y="140" font-size="12">${(hi*.01).toFixed(2)} μs</text></svg>`;return s;}
};
if(typeof module!=="undefined")module.exports=DSView;
if(typeof document!=="undefined"){
 const D=JSON.parse(document.getElementById('payload').textContent),S=D.summary,$=id=>document.getElementById(id),esc=DSView.esc;
 const labels={LOCAL_ENVELOPE_AVAILABLE:'模型可用',NO_MARK_WINDOW:'零毛刺无快照',MISSING_WINDOW:'缺少快照',UNKNOWN_OR_UNRETIRED:'UNKNOWN/未退役',NOT_CAPTURED:'未采集',UNALIGNED:'未对齐',MODEL_CONTRADICTED:'模型矛盾',INTEGRITY_ERROR:'完整性失败',ANALYSIS_CANCELLED:'已中断',NOT_ANALYZED:'未分析',NOT_ANALYZED_AFTER_INTEGRITY_FAILURE:'被阻断'};
 const name=p=>`d${p.d} / s${p.s>=0?'+':''}${p.s}`;const inSet=(set,p)=>(set||[]).some(x=>x.d===p.d&&x.s===p.s);
 $('session').textContent=`${S.session} · ${S.job_state} · 原件来源 ${S.stimulus_origin} · 种子 ${S.random_seed==null?'未声明':S.random_seed}`;
 $('scope').textContent=`局部软件推演：每块仅采集4096点，不能据此证明整图最优。${S.unmeasured_prefix_assumption?'本次使用未采集理想前缀作模型预热；它是参考辅助假设。':'本次仅使用CAP冷启动模型，不添加参考前缀。'} 全部ITEM统一使用一组浏览d/s。`;
 $('candidate').textContent=S.global_minimax_candidate_set.length?S.global_minimax_candidate_set.map(name).join('；'):'证据不足，未给出全64候选';
 const local=S.local_reference;const localReady=local&&local.state==='AVAILABLE'&&local.candidate_set.length>0;
 const viewProfile=p=>!p||!localReady||S.global_minimax_candidate_set.length?p:Object.assign({},p,local.profiles.find(x=>x.d===p.d&&x.s===p.s),{unresolved_windows:64-local.covered_windows});
 let localBox=$('localReference');if(!localBox){localBox=document.createElement('div');localBox.id='localReference';localBox.className='ds-local-reference';$('candidate').insertAdjacentElement('beforebegin',localBox);}
 localBox.hidden=!!S.global_minimax_candidate_set.length||!local;
 if(local){localBox.textContent=localReady?'局部参考候选：'+local.candidate_set.map(name).join('；')+'\n基于'+local.covered_windows+'/'+local.expected_windows+'块（'+(local.coverage_fraction*100).toFixed(1)+'%），仅供参考。所有候选比较同一组有效窗口；不覆盖未评估块，不代表整图最优或实板推荐。\n未参与：'+(local.excluded_items.length?local.excluded_items.map(x=>'第'+(x.item_index+1)+'块（ITEM索引'+x.item_index+'）').join('、'):'无'):(local.state==='BLOCKED_EVIDENCE'?'局部参考候选：证据完整性异常或分析中断，未提供。':'局部参考候选：暂无共同有效窗口。');}
 $('threshold').textContent=S.threshold_candidate_region.length?'达到声明门槛：'+S.threshold_candidate_region.map(name).join('；'):'没有配置达到声明门槛；最低上界候选不等于零错或硬件验证区域。';
 $('coverage').textContent=`有接收证据 ${S.provided_ITEMS}/64；模型可用 ${S.usable_windows}/64；目标在所有保留相位均匹配 ${S.current_target_all_phase_matches}/64。门槛：位错≤${S.acceptance_thresholds.max_local_bit_errors}，停止位错≤${S.acceptance_thresholds.max_local_framing_errors}。`;
 const b=S.actual_full_frame_observations.B;
 $('measured').textContent=`${S.actual_profile?name(S.actual_profile):'实际配置不可确认'}：完整帧正确 ${b.frame_correct}/${b.retired_items_with_bytes}；等长帧位置误码 ${b.positional_frame_bit_errors}（${b.equal_length_items}块可比）；局部实测错误 ${S.actual_local_bit_errors_from_saved_bytes}。`;
 $('profile').innerHTML=S.profiles.map(p=>`<option value="${DSView.key(p)}">${name(p)}</option>`).join('');
 const initial=S.global_minimax_candidate_set[0]||(localReady?local.candidate_set[0]:null)||S.actual_profile||S.profiles[0];$('profile').value=DSView.key(initial);
 $('item').innerHTML=D.items.map((i,n)=>`<option value="${n}">ITEM ${String(n).padStart(2,'0')} · ${labels[i.state]||i.state}</option>`).join('');
 $('bit').innerHTML=Array.from({length:9},(_,n)=>`<option value="${n}">${n===8?'STOP':n}</option>`).join('');
 $('audit').textContent=JSON.stringify({job_state:S.job_state,source_sha256:S.source_sha256,alignment_policy:S.alignment_policy,input_gate:S.input_gate,errors:S.errors,evidence_scope:S.evidence_audit_scope,hardware_verified_region:S.hardware_verified_region,hardware_access:false,new_STARTs:0},null,2);
 function grid(){let html='<tr><th>d / s</th>'+[-2,-1,0,1,2].map(s=>`<th>${s}</th>`).join('')+'</tr>';for(let d=1;d<=4;d++){html+=`<tr><th>${d}</th>`;for(let s=-2;s<=2;s++){const p=viewProfile(S.profiles.find(p=>p.d===d&&p.s===s));if(!p){html+='<td class="muted">—</td>';continue;}const key=DSView.key(p),classes=[inSet(S.global_minimax_candidate_set,p)?'best':'',localReady&&!S.global_minimax_candidate_set.length&&inSet(local.candidate_set,p)?'localbest':'',inSet(S.threshold_candidate_region,p)?'accepted':'',key===$('profile').value?'active':''].join(' ');html+=`<td><button class="${classes}" data-ds="${key}">${p.bit_errors_lower_bound}～${p.bit_errors_upper_bound}<br><small>${p.evaluated_windows}/64${p.eligible_for_global_software_ranking?'':' · 不参与全局排名'}</small></button></td>`;}html+='</tr>';} $('grid').innerHTML=html;$('grid').querySelectorAll('button').forEach(el=>el.onclick=()=>{$('profile').value=el.dataset.ds;chooseProfile();});}
 function cards(){ $('items').innerHTML=D.items.map((i,n)=>`<button data-item="${n}" class="${i.state==='LOCAL_ENVELOPE_AVAILABLE'?'good':i.state.includes('INTEGRITY')?'error':'gap'} ${n===Number($('item').value)?'active':''}">${String(n).padStart(2,'0')}<br>${esc(labels[i.state]||i.state)}</button>`).join('');$('items').querySelectorAll('button').forEach(el=>el.onclick=()=>{$('item').value=el.dataset.item;chooseItem();});}
 function item(){return D.items[Number($('item').value)];}
 function chooseProfile(){grid();const p=viewProfile(S.profiles.find(p=>DSView.key(p)===$('profile').value));$('profileDetail').textContent=`${name(p)}，比较${p.compared_local_bits}个局部位；停止位错误界${p.framing_errors_lower_bound}～${p.framing_errors_upper_bound}；未解决窗口${p.unresolved_windows}。`;chooseItem();}
 function chooseItem(){cards();const i=item(),old=$('phase').value,sc=DSView.options(i,$('profile').value);$('phase').innerHTML=sc.map(s=>`<option value="${s[0]}">${s[0]}${s[1]?'':'（未对齐）'}</option>`).join('');if(sc.some(s=>String(s[0])===old))$('phase').value=old;$('bit').value=String(i.target_bit==null?0:i.target_bit);$('itemDetail').textContent=`record ${i.record_id} · ${labels[i.state]||i.state} · 毛刺 ${JSON.stringify(i.stimulus||null)} · 保留相位${i.phase_count||0}个${i.reason?' · '+i.reason:''}`;choosePhase();}
 function scenario(){return DSView.options(item(),$('profile').value).find(s=>String(s[0])===$('phase').value);}
 function choosePhase(){const sc=scenario(),old=$('byte').value;$('byte').innerHTML=(sc?sc[4]:[]).map(f=>`<option value="${f[0]}">帧byte ${f[0]} / 载荷偏移 ${f[0]-20}</option>`).join('');if(sc&&sc[4].some(f=>String(f[0])===old))$('byte').value=old;draw();}
 function draw(){const i=item(),sc=scenario(),frames=sc?sc[4]:[],f=frames.find(f=>String(f[0])===$('byte').value),bit=Number($('bit').value);let lo=0,hi=4095;if($('zoom').value==='mark'){lo=1750;hi=2350;}if($('zoom').value==='byte'&&f){lo=Math.max(0,f[1]-30);hi=Math.min(4095,f[1]+1030);}const markers=f?f[5].filter(v=>v[0]===bit).flatMap(v=>[[v[1],v[4]],[v[2],v[5]],[v[3],v[6]]]):[];
 $('ideal').innerHTML=DSView.svg(DSView.ideal(i),lo,hi,'#2869a0');$('actual').innerHTML=DSView.svg(DSView.expand(i.raw),lo,hi,'#ba4934',markers);$('reconstructed').innerHTML=DSView.svg(DSView.reconstruct(frames),lo,hi,'#187e63');
 $('votes').innerHTML=f?f[5].map(v=>{const truth=v[0]===8?1:(i.source[f[0]]>>v[0])&1;return `<tr><td>${v[0]===8?'STOP':v[0]}</td><td>${v.slice(1,4).join(', ')}</td><td>${v.slice(4,7).join(', ')}</td><td>${v[7]}</td><td>${truth}</td><td class="${v[7]===truth?'ok':'bad'}">${v[7]===truth?'一致':'不一致'}</td></tr>`;}).join(''):'<tr><td colspan="6">该配置/相位没有可对齐的完整字节，不补造判决。</td></tr>';
 $('byteDetail').textContent=f?`参考字节0x${i.source[f[0]].toString(16).padStart(2,'0')}；原B接收0x${i.actual_B[f[0]].toString(16).padStart(2,'0')}（标志${i.actual_B_flags[f[0]]}）；软件候选0x${f[3].toString(16).padStart(2,'0')}；停止位错误${f[4]}。`:'无可用字节；实际波形存在时仍可查看。';}
 function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('profile').onchange=chooseProfile;$('item').onchange=chooseItem;$('phase').onchange=choosePhase;['byte','bit','zoom'].forEach(n=>$(n).onchange=draw);
 $('exportJson').onclick=()=>download(JSON.stringify(S,null,2),'ds_summary.json','application/json');$('exportCsv').onclick=()=>download('\ufeff'+DSView.csv(S.profiles,S),'ds_profiles.csv','text/csv;charset=utf-8');
 $('exportSvg').onclick=()=>{const names=['ideal','actual','reconstructed'];let svg='<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="530"><rect width="100%" height="100%" fill="white"/>';names.forEach((n,k)=>{svg+=`<text x="20" y="${k*175+18}" font-size="14">${k+1}. ${['Source reference','Captured digital input','Software reconstruction; illustrative phase '+$('phase').value][k]}</text><g transform="translate(0,${k*175+23})">`+$(n).querySelector('svg').innerHTML+'</g>';});svg+='</svg>';download(svg,`record${item().record_id}_ds${$('profile').value.replace(',','_')}.svg`,'image/svg+xml');};
 chooseProfile();
}
